// 予約サイトの入口。選んだ日の予約を作る
import express from 'express';
import { parseDay } from 'date-lib';

const app = express();
app.get('/api/reserve', (req, res) => {
  res.json({ date: parseDay(String(req.query.date)) });
});
app.listen(3000);
